from __future__ import annotations
import time
import traceback
from collections.abc import Callable
from typing import Any
import numpy as np
from autokernel_pbt.props.backends.base import OUTPUT_NAME, TELEMETRY_BACKEND, TELEMETRY_WALL_MS, ExecutionResult, OutputContractError, Status, kernel_inputs, readonly_inputs, single_output
from autokernel_pbt.props.case import Case

class NumpyBackend:
    name = 'numpy'

    def run(self, kernel: Callable[..., np.ndarray], case: Case) -> ExecutionResult:
        inputs = kernel_inputs(case)
        start = time.perf_counter()
        try:
            with readonly_inputs(inputs):
                output = kernel(**inputs)
        except Exception as exc:
            return self._failed(case, start, Status.LAUNCH_ERROR, exc)
        try:
            array = single_output(output)
        except OutputContractError as exc:
            return self._failed(case, start, Status.OUTPUT_ERROR, exc)
        return ExecutionResult(case=case, outputs={OUTPUT_NAME: array}, telemetry=self._telemetry(start), status=Status.OK)

    def _telemetry(self, start: float) -> dict[str, Any]:
        return {TELEMETRY_BACKEND: self.name, TELEMETRY_WALL_MS: (time.perf_counter() - start) * 1000.0}

    def _failed(self, case: Case, start: float, status: Status, exc: BaseException) -> ExecutionResult:
        return ExecutionResult(case=case, telemetry=self._telemetry(start), status=status, error=''.join(traceback.format_exception(exc)))

