from __future__ import annotations
from dataclasses import dataclass
from pathlib import Path
from typing import Any
import yaml
from autokernel_pbt.props.oracle import DeclarativeOracle
from autokernel_pbt.props.properties import CASE_PROPERTY_REGISTRY, GROUP_PROPERTY_REGISTRY, CaseProperty, GroupProperty
PROPERTY_CHECK = 'property'
KERNEL_TASKS_DIR = Path('kernels') / 'tasks'
CONTRACT_FILENAME = 'acceptance.yaml'
CONTRACT_VERSION = 1
_REQUIRED_CRITERION_KEYS = ('id', 'description', 'check')

class UnknownPropertyError(KeyError):
    pass

@dataclass(frozen=True)
class Criterion:
    id: str
    description: str
    property_name: str

@dataclass(frozen=True)
class Contract:
    task_id: str
    criteria: tuple[Criterion, ...]

    @property
    def property_names(self) -> tuple[str, ...]:
        return tuple((criterion.property_name for criterion in self.criteria))

def contract_paths(root: Path) -> tuple[Path, ...]:
    return tuple(sorted((root / KERNEL_TASKS_DIR).glob(f'*/{CONTRACT_FILENAME}')))

def _criterion_from(path: Path, task_id: str, raw: Any) -> Criterion:
    if not isinstance(raw, dict):
        msg = f'contract {path} for task {task_id!r} has a criterion that is not a mapping: {raw!r}'
        raise ValueError(msg)
    missing = [key for key in _REQUIRED_CRITERION_KEYS if key not in raw]
    if missing:
        msg = f'contract {path} for task {task_id!r} has a criterion missing required key(s) {missing}: {raw!r}'
        raise ValueError(msg)
    criterion_id = raw['id']
    if not isinstance(criterion_id, str) or not criterion_id.strip():
        msg = f"contract {path} for task {task_id!r} has a criterion with a blank id ({criterion_id!r}); a criterion with no id is not traceable to an obligation, and a bare 'id:' key parses as None rather than as text"
        raise ValueError(msg)
    check = raw['check']
    if not isinstance(check, dict):
        msg = f'contract {path} criterion {criterion_id!r} has a check that is not a mapping'
        raise ValueError(msg)
    check_type = check.get('type')
    if check_type != PROPERTY_CHECK:
        msg = f'contract {path} criterion {criterion_id!r} uses unknown check type {check_type!r}; a kernel contract understands only {PROPERTY_CHECK!r}, and a criterion this loader skipped would be a law nobody checks'
        raise ValueError(msg)
    if PROPERTY_CHECK not in check:
        msg = f"contract {path} criterion {criterion_id!r} is missing required key ['{PROPERTY_CHECK}'] under check"
        raise ValueError(msg)
    description = raw['description']
    if not isinstance(description, str) or not description.strip():
        msg = f'contract {path} criterion {criterion_id!r} has an empty description ({description!r}); the description is the spec half of the contract, and without it the file is a property list rather than a statement about the kernel'
        raise ValueError(msg)
    return Criterion(id=criterion_id, description=description, property_name=str(check[PROPERTY_CHECK]))

def load_contract(path: Path | str) -> Contract:
    path = Path(path)
    document = yaml.safe_load(path.read_text())
    if not isinstance(document, dict):
        msg = f'contract {path} is not a mapping; got {type(document).__name__}'
        raise ValueError(msg)
    task_id = str(document.get('task_id') or '').strip()
    if not task_id:
        msg = f'contract {path} declares no task_id; a contract naming no task cannot be joined to the corpus it is meant to score'
        raise ValueError(msg)
    version = document.get('version', CONTRACT_VERSION)
    if version != CONTRACT_VERSION:
        msg = f"contract {path} for task {task_id!r} declares version {version!r}; this loader understands only version {CONTRACT_VERSION}, and parsing a future format under today's rules would silently drop whatever it added"
        raise ValueError(msg)
    raw_criteria = document.get('criteria') or []
    if not isinstance(raw_criteria, list) or not raw_criteria:
        msg = f'contract {path} for task {task_id!r} declares no criteria; an oracle with no properties judges nothing, summarizes to INCONCLUSIVE, and silently adds groups that established nothing to the denominator of the detection rate'
        raise ValueError(msg)
    criteria = tuple((_criterion_from(path, task_id, raw) for raw in raw_criteria))
    ids = [criterion.id for criterion in criteria]
    duplicate_ids = sorted({cid for cid in ids if ids.count(cid) > 1})
    if duplicate_ids:
        msg = f'contract {path} for task {task_id!r} has duplicate criterion ids {duplicate_ids}; two obligations under one id are not separately traceable'
        raise ValueError(msg)
    seen: set[str] = set()
    for criterion in criteria:
        if criterion.property_name in seen:
            msg = f'contract {path} names property {criterion.property_name!r} twice; it would be evaluated twice and counted twice in every per-property tally'
            raise ValueError(msg)
        seen.add(criterion.property_name)
    return Contract(task_id=task_id, criteria=criteria)

def oracle_from_contract(contract: Contract) -> DeclarativeOracle:
    case_properties: list[CaseProperty] = []
    group_properties: list[GroupProperty] = []
    for name in contract.property_names:
        if name in CASE_PROPERTY_REGISTRY:
            case_properties.append(CASE_PROPERTY_REGISTRY[name]())
        elif name in GROUP_PROPERTY_REGISTRY:
            group_properties.append(GROUP_PROPERTY_REGISTRY[name]())
        else:
            known = sorted({*CASE_PROPERTY_REGISTRY, *GROUP_PROPERTY_REGISTRY})
            msg = f'contract for task {contract.task_id!r} names property {name!r}, which is not registered; known properties are {known}'
            raise UnknownPropertyError(msg)
    return DeclarativeOracle(case_properties, group_properties)

