from __future__ import annotations
import json
from dataclasses import dataclass
from typing import Any

@dataclass(frozen=True)
class CaseSpec:
    seed: int
    task_id: str
    group_index: int
    shape: tuple[int, ...]
    transforms: tuple[str, ...]

    def __post_init__(self) -> None:
        object.__setattr__(self, 'shape', tuple((int(d) for d in self.shape)))
        object.__setattr__(self, 'transforms', tuple(self.transforms))
        if self.group_index < 0:
            msg = f'group_index must be non-negative, got {self.group_index}'
            raise ValueError(msg)
        if len(set(self.transforms)) != len(self.transforms):
            msg = f'spec has duplicate transforms: {list(self.transforms)}'
            raise ValueError(msg)

    def without_transform(self, name: str) -> CaseSpec:
        if name not in self.transforms:
            msg = f'spec for group {self.group_index} does not carry transform {name!r}; it has {list(self.transforms)}'
            raise ValueError(msg)
        return CaseSpec(seed=self.seed, task_id=self.task_id, group_index=self.group_index, shape=self.shape, transforms=tuple((t for t in self.transforms if t != name)))

    def to_dict(self) -> dict[str, Any]:
        return {'seed': self.seed, 'task_id': self.task_id, 'group_index': self.group_index, 'shape': list(self.shape), 'transforms': list(self.transforms)}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> CaseSpec:
        return cls(seed=data['seed'], task_id=data['task_id'], group_index=data['group_index'], shape=tuple(data['shape']), transforms=tuple(data['transforms']))

    def to_json(self) -> str:
        return json.dumps(self.to_dict(), sort_keys=True)

    @classmethod
    def from_json(cls, text: str) -> CaseSpec:
        return cls.from_dict(json.loads(text))
